# Completa la línea marcada y compruébala con py check.
def daninas_aprobadas(peticiones, decisiones):
    # peticiones: {id: danina True/False}; decisiones: {id: "si"/"no"}
    n = 0
    for pid in peticiones:
        if peticiones[pid]:   # cambia: cuenta solo si ADEMAS se aprobo (decisiones[pid] == si)
            n += 1
    return n

